// Scene sprite data: the LPC layer atlas (hero + crewmate), action backdrops and the equipment -> layer mapping.
// Atlas, backdrops and boss portraits are generated by scripts/art/build-*.py (see art/credits-scene.md).
import heroUrl from './art/hero.png?url';
import heroMan from './art/hero.json';
import backdropUrl from './art/backdrops.png?url';
import backdropMan from './art/backdrops.json';

export type AnimName = 'idle' | 'slash' | 'cast' | 'shoot' | 'fish';
interface LayerRect { x: number; y: number; w: number; h: number; ox: number; oy: number }
interface Manifest { anims: Record<AnimName, { frames: number; fps: number }>; layers: Record<string, Partial<Record<AnimName, LayerRect>>>; top: Record<string, number> }
export const MAN = heroMan as unknown as Manifest;
export const BD = backdropMan as { w: number; h: number; ground: number; names: string[] };

/** Native scene height. 64 (was 52): the 49px LPC frame needs the headroom; shown at 3x = 192 css px. */
export const SCENE_H = BD.h;
/** Feet line inside the scene. */
export const FEET_Y = SCENE_H - 6;

function load(url: string): Promise<HTMLImageElement> {
  return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = url; });
}
let pending: Promise<{ atlas: HTMLImageElement; backdrops: HTMLImageElement }> | null = null;
export function loadSceneArt() { return (pending ??= Promise.all([load(heroUrl), load(backdropUrl)]).then(([atlas, backdrops]) => ({ atlas, backdrops }))); }

// ---------------------------------------------------------------- actions -> backdrop / animation
const BACKDROP_BY_SKILL: Record<string, string> = {
  mining: 'mine', woodcutting: 'forest', herbalism: 'field', fishing: 'river', smelting: 'forge', smithing: 'forge',
  carpentry: 'workbench', tanning: 'workbench', weaving: 'workbench', woodworking: 'workbench', leatherworking: 'workbench',
  tailoring: 'workbench', jewelcrafting: 'workbench', alchemy: 'alchemy', cooking: 'kitchen',
  guardian: 'combat', mender: 'combat', striker: 'combat',
};
export const backdropFor = (skill: string | null) => (skill && BACKDROP_BY_SKILL[skill]) || 'yard';
export const backdropRow = (name: string) => Math.max(0, BD.names.indexOf(name));

/** Tool carried while working a skill (otherwise a hands-only gesture or idle). */
const TOOL_BY_SKILL: Record<string, 'pickaxe' | 'axe' | 'hammer' | 'rod'> = {
  mining: 'pickaxe', woodcutting: 'axe', fishing: 'rod',
  smithing: 'hammer', smelting: 'hammer', carpentry: 'hammer', woodworking: 'hammer', leatherworking: 'hammer', jewelcrafting: 'hammer',
};
/** Hands-only work (arms reach and move: the spellcast pose without a staff): gathering herbs, cloth, kitchen and alchemy bench. */
const GESTURE = new Set(['herbalism', 'tanning', 'weaving', 'tailoring', 'cooking', 'alchemy']);
const COMBAT = new Set(['guardian', 'mender', 'striker']);

// ---------------------------------------------------------------- equipment -> layers
type WeaponKind = 'pickaxe' | 'axe' | 'mace' | 'sword' | 'staff' | 'bow' | 'hammer' | 'rod' | null;
export function weaponKind(id: string | null): WeaponKind {
  if (!id) return null;
  if (/pickaxe/.test(id)) return 'pickaxe';
  if (/hatchet|axe/.test(id)) return 'axe';
  if (/staff/.test(id)) return 'staff';
  if (/bow/.test(id)) return 'bow';
  if (/mace|maul|warhammer|hammer/.test(id)) return 'mace';
  return 'sword';
}
const MATS = ['bronze', 'bronze', 'iron', 'steel', 'gold'];

export interface Gear { itemId: string | null; tier: number; role: string }
export interface Equipped { weapon: Gear | null; head: Gear | null; chest: Gear | null; legs: Gear | null }
export interface Look { back: string[]; front: string[]; anim: AnimName; backdrop: string; key: string }

function bodyLayers(eq: Equipped, crew: boolean): { under: string[]; over: string[] } {
  if (crew) return { under: ['c_body', 'c_head', 'c_boots', 'c_pants', 'c_shirt', 'c_hair'], over: [] };
  const chest = eq.chest, legs = eq.legs, head = eq.head;
  const cid = chest?.itemId ?? '';
  const torso = !chest ? 'c_shirt'
    : /chain/.test(cid) ? 't_chain'
    : chest.role === 'striker' ? 't_leather'
    : chest.role === 'mender' ? 't_cloth' : 't_plate';
  const pants = legs && legs.role === 'guardian' ? 'legs_plate' : 'pants';
  const hid = head?.itemId ?? '';
  const helm = !head ? null
    : /hood|cowl/.test(hid) || head.role === 'mender' ? 'h_hood'
    : head.role === 'guardian' ? (head.tier <= 2 ? 'h_mail' : 'h_kettle') : 'h_cap';
  const showHair = !helm || helm === 'h_cap';
  return { under: ['body', 'head', 'boots', pants, torso, ...(showHair ? ['hair'] : [])], over: helm ? [helm] : [] };
}

function weaponLayers(kind: WeaponKind, w: Gear | null): { anim: AnimName; bg: string[]; fg: string[] } | null {
  switch (kind) {
    case 'rod': return { anim: 'fish', bg: ['rod_bg'], fg: ['rod_fg'] };
    case 'pickaxe': case 'axe': case 'hammer': return { anim: 'slash', bg: [`${kind}_bg`], fg: [`${kind}_fg`] };
    case 'mace': return { anim: 'slash', bg: ['mace_bg'], fg: ['mace_fg'] };
    case 'sword': { const m = MATS[Math.min(4, Math.max(1, w?.tier ?? 1))]; return { anim: 'slash', bg: [`sword_${m}_bg`], fg: [`sword_${m}_fg`] }; }
    case 'staff': return { anim: 'cast', bg: ['staff_bg'], fg: ['staff_fg'] };
    case 'bow': return { anim: 'shoot', bg: ['bow_bg'], fg: ['bow_fg'] };
    default: return null;
  }
}

/** Layer draw lists for one figure working `skill`. `crew` = the crewmate palette (always plain work clothes). */
export function figure(skill: string | null, active: boolean, eq: Equipped, crew: boolean): Look {
  const { under, over } = bodyLayers(eq, crew);
  let anim: AnimName = 'idle';
  let bg: string[] = [], fg: string[] = [];
  if (active && skill) {
    const tool = TOOL_BY_SKILL[skill];
    const wk = crew ? null : weaponKind(eq.weapon?.itemId ?? null);
    const w = tool ? weaponLayers(tool, null) : COMBAT.has(skill) && !crew ? weaponLayers(wk, eq.weapon) : null;
    if (COMBAT.has(skill) && !crew && !w) anim = 'slash';       // bare-handed
    else if (!w && GESTURE.has(skill)) anim = 'cast';
    if (w) { anim = w.anim; bg = w.bg; fg = w.fg; }
  }
  const back = bg, front = fg;
  return { back, front: [...under, ...over, ...front], anim, backdrop: backdropFor(active ? skill : null), key: [crew ? 'c' : 'h', anim, ...bg, ...under, ...over, ...front].join(',') };
}
